          ".card {\n  width: 100%;\n  max-width: 440px;\n  margin: 0 auto;\n  padding: 20px;\n  border-radius: var(--radius-lg);\n}\n\n.cardTitle {\n  margin-left: 4px;\n}\n\n.form {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.footer {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.checkboxLabel {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  font-size: 0.875rem;\n  line-height: 20px;\n  font-weight: 300;\n  margin-left: 4px;\n  margin-top: 0.5rem;\n  cursor: pointer;\n}\n\n.button {\n  width: 100%;\n}\n\n.card .button:active:not([data-disabled]),\n.card .button[data-pressed],\n.card .socialButton:active:not([data-disabled]),\n.card .socialButton[data-pressed] {\n  transform: scale(0.993);\n}\n\n.buttonContent {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.spinner {\n  position: absolute;\n  right: 1rem;\n  animation: spin 0.6s linear infinite;\n}\n\n@keyframes spin {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n.emailField {\n  padding-bottom: 4px;\n}\n\n.fieldLabel {\n  margin-left: 4px;\n}\n\n.passwordLabelRow {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  width: 100%;\n}\n\n.forgotPassword {\n  background: none;\n  border: none;\n  padding: 0;\n  font-size: 0.875rem;\n  line-height: 20px;\n  color: var(--secondary-foreground);\n  cursor: pointer;\n  transition: color 0.2s;\n  margin-right: 4px;\n  font-weight: 300;\n}\n\n.forgotPassword:hover {\n  color: var(--foreground);\n}\n\n.rememberMe {\n  color: var(--secondary-foreground);\n  cursor: pointer;\n}\n.rememberMe:hover {\n  color: var(--foreground);\n}\n.signupBanner {\n  width: calc(100% + 40px);\n\n  margin-left: -20px;\n  margin-right: -20px;\n  margin-bottom: -20px;\n  margin-top: -8px;\n  text-align: center;\n  font-size: 0.875rem;\n  line-height: 20px;\n  padding: 1.25rem 0;\n  background-color: var(--mix-card-35-trans);\n\n  border-radius: 0 0 var(--radius-lg) var(--radius-lg);\n}\n\n.signupText {\n  color: var(--muted-foreground);\n}\n\n.signupLink {\n  background: none;\n  border: none;\n  padding: 0;\n  color: var(--secondary-foreground);\n  cursor: pointer;\n  font: inherit;\n\n  &:hover {\n    color: var(--foreground);\n  }\n}\n\n.dividerContainer {\n  display: flex;\n  align-items: center;\n  gap: 1rem;\n}\n\n.dividerLine {\n  flex: 1;\n  height: 1px;\n  background-color: var(--border);\n}\n\n.dividerText {\n  color: var(--muted-foreground);\n  font-size: 0.75rem;\n  line-height: 20px;\n  font-weight: 400;\n  padding: 0 0.5rem;\n}\n\n.socialLoginContainer {\n  display: flex;\n  flex-direction: column;\n  gap: 0.75rem;\n}\n\n.socialButton {\n  width: 100%;\n  display: flex;\n  gap: 0.5rem;\n  position: relative;\n}\n\n.socialIcon {\n  width: 1.25rem;\n  height: 1.25rem;\n}\n\n.appleLogo {\n  width: 1.25rem;\n  height: 1.25rem;\n  margin-left: -8px;\n}\n\n.lastUsedBadge {\n  position: absolute;\n  right: 12px;\n}\n\n@media (max-width: 640px) {\n  .card {\n    padding: 1rem;\n  }\n\n  .cardTitle {\n    font-size: 1.25rem;\n    line-height: 1.3;\n  }\n\n  .fieldLabel {\n    font-size: 0.875rem;\n  }\n\n  .checkboxLabel {\n    font-size: 0.875rem;\n    gap: 0.625rem;\n    min-height: 2.75rem;\n    align-items: center;\n  }\n\n  .forgotPassword {\n    font-size: 0.875rem;\n    min-height: 2.75rem;\n    padding: 0.5rem;\n    margin-right: 0;\n  }\n\n  .rememberMe {\n    font-size: 0.875rem;\n  }\n\n  .signupBanner {\n    width: calc(100% + 2rem);\n    margin-left: -1rem;\n    margin-right: -1rem;\n    margin-bottom: -1rem;\n    font-size: 0.9375rem;\n    padding: 1rem 0;\n  }\n\n  .dividerText {\n    font-size: 0.8125rem;\n  }\n\n  .socialButton {\n    min-height: 2.75rem;\n    font-size: 0.9375rem;\n    gap: 0.625rem;\n  }\n\n  .socialIcon,\n  .appleLogo {\n    width: 1.125rem;\n    height: 1.125rem;\n  }\n\n  .appleLogo {\n    margin-left: -4px;\n  }\n\n  .lastUsedBadge {\n    right: 8px;\n  }\n\n  .passwordLabelRow {\n    margin-bottom: 0.375rem;\n  }\n}\n",
