          '"use client";\nimport { Check } from "lucide-react";\nimport { useId, useState } from "react";\nimport { Badge } from "../../ui/badge/badge";\nimport { Button } from "../../ui/button/button";\nimport { Card, CardContent, CardHeader, CardTitle } from "../../ui/card/card";\nimport { Checkbox, CheckboxIndicator } from "../../ui/checkbox/checkbox";\nimport { Field, FieldError, FieldLabel } from "../../ui/field/field";\nimport { Form, FormActions, FormGroup } from "../../ui/form/form";\nimport { Input } from "../../ui/input/input";\nimport styles from "./card-login.module.css";\n\nexport type CardLoginProps = {\n  onSignIn?: (credentials: { email: string; password: string; rememberMe: boolean }) => void | Promise<void>;\n  onForgotPassword?: () => void;\n  onSignUp?: () => void;\n  onSocialSignIn?: (provider: "apple" | "google") => void;\n};\n\nexport default function CardLoginDemo({ onSignIn, onForgotPassword, onSignUp, onSocialSignIn }: CardLoginProps = {}) {\n  const rememberId = useId();\n  const [pending, setPending] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    if (pending) {\n      return;\n    }\n    const form = e.currentTarget;\n    setError(null);\n    if (!onSignIn) {\n      return;\n    }\n    const data = new FormData(form);\n    setPending(true);\n    try {\n      await onSignIn({\n        email: String(data.get("email") ?? ""),\n        password: String(data.get("password") ?? ""),\n        rememberMe: data.get("rememberMe") !== null,\n      });\n      form.reset();\n    } catch {\n      setError("Unable to sign in. Please try again.");\n    } finally {\n      setPending(false);\n    }\n  };\n\n  return (\n    <Card className={styles.card}>\n      <CardHeader>\n        <CardTitle className={styles.cardTitle}>Sign In</CardTitle>\n      </CardHeader>\n      <CardContent>\n        <Form className={styles.form} onSubmit={handleSubmit}>\n          <FormGroup>\n            <Field className={styles.emailField}>\n              <FieldLabel className={styles.fieldLabel}>Email</FieldLabel>\n              <Input\n                autoComplete="email"\n                name="email"\n                placeholder="Enter your email…"\n                required\n                spellCheck={false}\n                type="email"\n              />\n              <FieldError />\n            </Field>\n\n            <Field>\n              <div className={styles.passwordLabelRow}>\n                <FieldLabel className={styles.fieldLabel}>Password</FieldLabel>\n                <button\n                  className={styles.forgotPassword}\n                  disabled={!onForgotPassword || pending}\n                  onClick={onForgotPassword}\n                  type="button"\n                >\n                  Forgot password?\n                </button>\n              </div>\n              <Input\n                autoComplete="current-password"\n                name="password"\n                placeholder="Enter your password…"\n                required\n                type="password"\n              />\n              <FieldError />\n            </Field>\n\n            <label className={styles.checkboxLabel} htmlFor={rememberId}>\n              <Checkbox defaultChecked={false} id={rememberId} name="rememberMe">\n                <CheckboxIndicator>\n                  <Check size={16} strokeWidth={3} />\n                </CheckboxIndicator>\n              </Checkbox>\n              <span className={styles.rememberMe}>Remember me</span>\n            </label>\n          </FormGroup>\n\n          <FormActions className={styles.footer}>\n            <Button className={styles.button} disabled={pending} type="submit">\n              <span className={styles.buttonContent}>{pending ? "Signing in…" : "Sign In"}</span>\n            </Button>\n          </FormActions>\n          {error ? <p role="alert">{error}</p> : null}\n        </Form>\n      </CardContent>\n      <div className={styles.dividerContainer}>\n        <div className={styles.dividerLine} />\n        <span className={styles.dividerText}>OR</span>\n        <div className={styles.dividerLine} />\n      </div>\n      <div className={styles.socialLoginContainer}>\n        <Button\n          className={styles.socialButton}\n          disabled={!onSocialSignIn || pending}\n          onClick={() => onSocialSignIn?.("apple")}\n          variant="outline"\n        >\n          <AppleIcon className={styles.appleLogo} />\n          Apple\n        </Button>\n        <Button\n          className={styles.socialButton}\n          disabled={!onSocialSignIn || pending}\n          onClick={() => onSocialSignIn?.("google")}\n          variant="outline"\n        >\n          <GoogleIcon className={styles.socialIcon} />\n          Google\n          <Badge className={styles.lastUsedBadge} size="sm" variant="info">\n            Last used\n          </Badge>\n        </Button>\n      </div>\n      <div className={styles.signupBanner}>\n        <span className={styles.signupText}>No account? </span>\n        <button className={styles.signupLink} disabled={!onSignUp || pending} onClick={onSignUp} type="button">\n          Sign up\n        </button>\n      </div>\n    </Card>\n  );\n}\n\nfunction AppleIcon({ className }: { className?: string }) {\n  return (\n    <svg aria-hidden="true" className={className} viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">\n      <path\n        d="M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701"\n        fill="currentColor"\n      />\n    </svg>\n  );\n}\n\nfunction GoogleIcon({ className }: { className?: string }) {\n  return (\n    <svg aria-hidden="true" className={className} viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">\n      <path\n        d="M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .307 5.387.307 12s5.56 12 12.173 12c3.573 0 6.267-1.173 8.373-3.36 2.16-2.16 2.84-5.213 2.84-7.667 0-.76-.053-1.467-.173-2.053H12.48z"\n        fill="currentColor"\n      />\n    </svg>\n  );\n}\n',
