          ".cardContainer {\n  width: 100%;\n  max-width: 600px;\n}\n\n.chartContainer {\n  height: 200px;\n  padding: 0;\n}\n\n.statsGrid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  grid-template-rows: 1fr 1fr;\n  border-top: 0.5px solid oklch(from var(--border) l c h / 0.7);\n  margin: 0 -24px -24px -24px;\n}\n\n.statCard {\n  padding: 1rem;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  border-right: 0.5px solid oklch(from var(--border) l c h / 0.7);\n  border-bottom: 0.5px solid oklch(from var(--border) l c h / 0.7);\n}\n\n.statCard:nth-child(2n) {\n  border-right: none;\n}\n\n.statCard:nth-child(n + 3) {\n  border-bottom: none;\n}\n\n@media (max-width: 640px) {\n  .cardContainer {\n    max-width: 100%;\n  }\n\n  .chartContainer {\n    height: 200px;\n  }\n\n  .statsGrid {\n    margin: 0 -20px -20px -20px;\n  }\n\n  .statCard {\n    padding: 1rem;\n    gap: 0.5rem;\n  }\n\n  .statLabel {\n    font-size: 0.875rem;\n  }\n\n  .statNumber {\n    font-size: 1.75rem;\n    font-weight: 700;\n  }\n}\n\n@media (max-width: 400px) {\n  .statsGrid {\n    grid-template-columns: 1fr;\n    grid-template-rows: auto;\n    margin: 0 -20px -20px -20px;\n  }\n\n  .statCard {\n    border-right: none;\n    border-bottom: 1px solid var(--border);\n    padding: 1rem;\n  }\n\n  .statCard:nth-child(2n) {\n    border-right: none;\n  }\n\n  .statCard:nth-child(n + 3) {\n    border-bottom: 1px solid var(--border);\n  }\n\n  .statCard:last-child {\n    border-bottom: none;\n  }\n\n  .statNumber {\n    font-size: 1.5rem;\n  }\n}\n\n.statHeader {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.statLabel {\n  font-size: 14px;\n  line-height: 20px;\n  color: var(--muted-foreground);\n  font-weight: 500;\n}\n\n.statNumber {\n  font-size: 32px;\n  font-weight: 700;\n  color: var(--foreground);\n  line-height: 1;\n  font-variant-numeric: tabular-nums;\n}\n",
