          ".wrapper {\n  width: 100%;\n  max-width: 100%;\n  padding: 24px 0;\n}\n\n.header {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 24px;\n  margin-bottom: 32px;\n  padding-inline: 1rem;\n}\n\n.heading {\n  font-size: clamp(2rem, 5vw, 3rem);\n  font-weight: 500;\n  color: var(--foreground);\n  margin: 0;\n  letter-spacing: -0.02em;\n  line-height: 1.3;\n}\n\n.description {\n  font-size: var(--font-size-sm);\n  color: var(--muted-foreground);\n  margin: 0;\n  max-width: 360px;\n  text-align: left;\n}\n\n@media (max-width: 768px) {\n  .header {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .heading {\n    font-size: clamp(1.875rem, 5vw, 2.75rem);\n  }\n}\n\n.bleed {\n}\n\n.carouselRoot {\n}\n\n.content {\n  height: 50vh;\n  align-items: center;\n  justify-content: center;\n}\n\n@media (min-width: 1100px) {\n  .header {\n    max-width: 1008px;\n    margin-left: auto;\n    margin-right: auto;\n    padding-inline: 0;\n  }\n\n  .bleed {\n    width: auto;\n    margin-left: 0;\n    margin-right: 0;\n    left: auto;\n    right: auto;\n    display: flex;\n    justify-content: center;\n  }\n\n  .carouselRoot {\n    width: auto;\n  }\n}\n\n.content p {\n  margin: 0 0 1rem 0;\n}\n\n.content p:last-child {\n  margin-bottom: 0;\n}\n",
