        content:
          '"use client";\nimport { Carousel } from "../../ui/carousel/carousel";\nimport { ExpandableCard, type ExpandableCardItem } from "../../ui/expandable-card/expandable-card";\nimport styles from "./expandable-card-carousel.module.css";\n\ntype CardData = {\n  id: number;\n  imageSrc: string;\n  cardHeading: string;\n  alt: string;\n  paragraphs: string[];\n};\n\ntype ExpandableCardCarouselProps = {\n  data: {\n    cards: CardData[];\n  };\n};\n\nexport function ExpandableCardCarousel({ data }: ExpandableCardCarouselProps) {\n  const items: ExpandableCardItem[] = data.cards.map((card) => ({\n    id: card.id,\n    imageSrc: card.imageSrc,\n    cardHeading: card.cardHeading,\n    alt: card.alt,\n    content: (\n      <div className={styles.content}>\n        {card.paragraphs.map((paragraph) => (\n          <p key={paragraph}>{paragraph}</p>\n        ))}\n      </div>\n    ),\n  }));\n\n  return (\n    <div className={styles.wrapper}>\n      <header className={styles.header}>\n        <h2 className={styles.heading}>\n          Our Three Core\n          <br />\n          Philosophies\n        </h2>\n        <p className={styles.description}>\n          The principles that guide everything we create, from design decisions to the experiences we craft for our\n          users.\n        </p>\n      </header>\n      <Carousel.Bleed className={styles.bleed}>\n        <Carousel.Root align="start" className={styles.carouselRoot} gap={24} totalItems={items.length} variant="inset">\n          <Carousel.Viewport>\n            <Carousel.Content className={styles.content}>\n              {items.map((item, index) => (\n                <Carousel.Item index={index} key={item.id}>\n                  <ExpandableCard item={item} />\n                </Carousel.Item>\n              ))}\n            </Carousel.Content>\n          </Carousel.Viewport>\n        </Carousel.Root>\n      </Carousel.Bleed>\n    </div>\n  );\n}\n',
